% Detlog code generated by detlog2 from examples/output.pl
% No cuts and no choicepoints: every predicate succeeds exactly once and
% returns its answer packet (rows and out(Text) items) in its last argument.
% Run it with: detlog2 run --det FILE 'p__cp(Args..., Packet)'
%
% predicate_to_packet(gen/1, 1 clauses)
% member_to_member_cp
% predicate_to_packet(show/0, 2 clauses)
% predicate_to_packet(pairs/0, 2 clauses)
% predicate_to_packet(first_big/1, 1 clauses)
% member_to_member_cp
% if_then_else_to_if_commit
% predicate_to_packet(count_out/1, 1 clauses)
% predicate_to_packet(logged/1, 1 clauses)
% findall_to_packet
% proof accepted: 30 steps, 46 clauses justified

gen__cp(A1, Rows) :-
    gen__cp_c1([A1], Rows).

gen__cp_c1(Args, Rows) :-
    if_commit(
        copy_term(Args, [X]),
        (   member_cp(P, [1, 2]),
            cp_rows(P, PRows),
            splice_extend(PRows, [X], [X], R),
            gen_c1__cp_1(R, Env),
            splice_extend(Env, [X], [X], Rows)
        ),
        Rows = []
    ).

gen_c1__cp_1([], []).
gen_c1__cp_1([Row|Rows], Out) :-
    if_commit(
        Row = out(Text),
        Out1 = [out(Text)],
        (   copy_term(Row, [X]),
            effect_text(write(g(X)), Text1),
            Out1 = [out(Text1), [X]]
        )
    ),
    gen_c1__cp_1(Rows, Out2),
    rows_concat([Out1, Out2], Out).

show__cp(Rows) :-
    show__cp_c1([], R1),
    show__cp_c2([], R2),
    rows_concat([R1, R2], Rows).

show__cp_c1(Args, Rows) :-
    if_commit(
        copy_term(Args, []),
        (   gen__cp(X, Packet),
            splice_extend(Packet, [X], [X], R),
            show_c1__cp_1(R, Env),
            splice_extend(Env, [], [X], Rows)
        ),
        Rows = []
    ).

