first_big__cp(A1, Rows) :-
    first_big__cp_c1([A1], Rows).

first_big__cp_c1(Args, Rows) :-
    if_commit(
        copy_term(Args, [X]),
        (   first_big_c1__cp_1([[X]], Cond),
            packet_first(Cond, Pre, Res),
            if_commit(
                Res = none,
                (   OutE = [],
                    rows_concat([Pre, OutE], Env)
                ),
                (   Res = first(First),
                    OutT = [First],
                    rows_concat([Pre, OutT], Env)
                )
            ),
            splice_extend(Env, [X], [X], Rows)
        ),
        Rows = []
    ).

