first_big_c1__cp_3([Row|Rows], Out) :-
    if_commit(
        Row = out(Text),
        Out1 = [out(Text)],
        (   copy_term(Row, [X]),
            if_commit(
                X > 3,
                Out1 = [[X]],
                Out1 = []
            )
        )
    ),
    first_big_c1__cp_3(Rows, Out2),
    rows_concat([Out1, Out2], Out).

