count_out__cp(A1, Rows) :-
    count_out__cp_c1([A1], Rows).

count_out__cp_c1(Args, Rows) :-
    if_commit(
        copy_term(Args, [N]),
        (   count_out_c1__cp_1([[N, V1]], Found),
            packet_split(Found, Outs, Rows0),
            length_det(Rows0, Count),
            if_commit(
                N = Count,
                rows_concat([Outs, [[N, V1]]], Env),
                Env = Outs
            ),
            splice_extend(Env, [N], [N, V1], Rows)
        ),
        Rows = []
    ).

count_out_c1__cp_1([], []).
count_out_c1__cp_1([Row|Rows], Out) :-
    if_commit(
        Row = out(Text),
        Out1 = [out(Text)],
        (   copy_term(Row, [N, V1]),
            gen__cp(V1, Packet),
            splice_extend(Packet, [N, V1], [V1], Out1)
        )
    ),
    count_out_c1__cp_1(Rows, Out2),
    rows_concat([Out1, Out2], Out).

