logged__cp_c1(Args, Rows) :-
    if_commit(
        copy_term(Args, [L]),
        (   logged_c1__cp_1([[L, X]], Found),
            packet_split(Found, Outs, Rows0),
            splice_extend(Rows0, X, [L, X], L1),
            if_commit(
                L = L1,
                rows_concat([Outs, [[L, X]]], R),
                R = Outs
            ),
            logged_c1__cp_4(R, Env),
            splice_extend(Env, [L], [L, X], Rows)
        ),
        Rows = []
    ).

